{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret hævder, at det normalt ikke er Udbetaling Danmark, der vurderer ansøgningen, men SU-myndigheden/Styrelsen for Institutioner og Uddannelsesstøtte. Det modsiger de frosne kilder (vejledningen og SU-bekendtgørelsen § 36-37), hvor Udbetaling Danmark er den vurderende myndighed. Svaret nævner heller ikke Skattestyrelsen som kilde til arbejdstimer og indkomst. Det nævner ikke, at arbejde før ansøgningen navnlig kan indgå, når ophøret skyldtes andre forhold og funktionsnedsættelsen ikke er forværret. Det nævner heller ikke eksplicit, at arbejde under studiet indgår."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Fire kritiske elementer kræves. (1) Skattestyrelsen som kilde til arbejdstimer og indkomst mangler. (2) Ansøgerens egne oplysninger om tidligere arbejde er kun delvist dækket, fordi svaret opregner oplysninger uden at sige, at ansøgeren selv skal angive dem. (3) Det mangler, at arbejde før ansøgningen kan indgå, navnlig når ophøret skyldtes andre forhold og der ikke er sket forværring. (4) Det mangler, at arbejde under studiet indgår."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet er, hvilke oplysninger Udbetaling Danmark bruger. Svaret bestrider, at Udbetaling Danmark er myndigheden, og giver en generisk liste over mulige oplysninger. Det besvarer ikke de væsentlige dele, nemlig Skattestyrelsens oplysninger, tidligere arbejde og arbejde under studiet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en myndighedsfordeling (SU-myndigheden/Styrelsen for Institutioner og Uddannelsesstøtte frem for Udbetaling Danmark), som de frosne kilder modsiger. Det tilføjer også uunderstøttede detaljer: hvilke job, arbejdsopgaver, tilpasninger og hvorfor job sluttede, samt at honorarer og selvstændig virksomhed indgår. Endelig tilføjer det, at vurderingen er adskilt fra reglerne om fribeløb."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer, at oplysningerne ikke alene afgør sagen. Det udelader den kvalifikation, at tidligere arbejde navnlig er relevant, når ophøret skyldtes andre forhold og der ikke er sket forværring."
    },
    "c09_reasoning_coherence": {
      "label": "not_met",
      "reason": "Svaret er internt nogenlunde sammenhængende i sin fremstilling, men hviler på den forkerte præmis om, at en anden myndighed vurderer sagen. Konklusionen om, hvilke oplysninger der indgår, er dermed ikke understøttet af de rette regler og kilder, og kerneelementerne mangler."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten er delvist korrekt (\"kan indgå\", \"afgør ikke automatisk\"). Svaret formulerer dog myndighedsspørgsmålet kategorisk (\"Det er normalt ikke Udbetaling Danmark\") i modstrid med kilderne. Det gengiver heller ikke kildens \"navnlig\"-modalitet om tidligere arbejde."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det peger desuden på en anden myndighed end Udbetaling Danmark."
    },
    "A19": {
      "label": "partial",
      "reason": "Svaret nævner oplysninger om job, tidspunkter og arbejdsopgaver, men ikke at ansøgeren selv skal angive tidligere arbejdsforhold i ansøgningen, og heller ikke at de inddrages."
    },
    "A20": {
      "label": "no",
      "reason": "Svaret dækker hverken, at erhvervsarbejde før ansøgningen kan indgå, navnlig ved arbejdsophør af andre grunde uden forværring, eller at arbejde under studiet indgår."
    }
  },
  "overall_notes": "Svaret er uden kilder og har en væsentlig juridisk fejl i myndighedsangivelsen. Det udelader tre af de fire kritiske elementer: Skattestyrelsen, tidligere arbejde med \"navnlig\"-betingelsen og arbejde under studiet. Svaret rammer korrekt, at oplysningerne indgår i en samlet vurdering og ikke automatisk afgør sagen."
}

